const assert=require("node:assert/strict");
const fs=require("node:fs");
const src=fs.readFileSync("src/app/components/ziiply/cards/ZiiplyMobileCompareCardresponsive.tsx","utf8");
assert.match(src,/function getMatchedCartItemIds\(store: ZiiplyCompareStore\)/);
assert.match(src,/function hasSameMatchedItems\(a: ZiiplyCompareStore, b: ZiiplyCompareStore\)/);
assert.match(src,/if \(storeMissing > 0 && !hasSameMatchedItems\(store, cheapest\)\) return null;/);
assert.match(src,/const isBest = !hasNoCounterpart && Boolean\(cheapest\?\.id === store\.id\) &&/);
assert.match(src,/Math\.max\(0, Number\(store\.missingItems \|\| 0\)\) === 0\);/);
assert.match(src,/const diffLabel = hasNoCounterpart \|\| Math\.max\(0, Number\(store\.missingItems \|\| 0\)\) > 0/);
const ids=s=>(s.matches||[]).map(m=>String(m.cartItemId||"").trim()).filter(Boolean).sort();
const same=(a,b)=>{const x=ids(a),y=ids(b);return x.length===y.length&&x.every((id,i)=>id===y[i])};
const s={id:"S",totalPrice:400,itemCount:2,missingItems:1,matches:[{cartItemId:"A"},{cartItemId:"B"}]};
const k={id:"K",totalPrice:300,itemCount:2,missingItems:1,matches:[{cartItemId:"A"},{cartItemId:"C"}]};
assert.equal(same(s,k),false,"same 2/3 coverage is not same product content");
assert.equal(same(s,{...k,matches:[{cartItemId:"B"},{cartItemId:"A"}]}),true);
const bestEligible=x=>x.missingItems===0;
assert.equal(bestEligible(s),false);
assert.equal(bestEligible(k),false);
const label=(store,cheapest)=>store.missingItems>0?null:store.totalPrice-cheapest.totalPrice;
assert.equal(label(s,k),null);
assert.equal(label(k,s),null);
console.log("PASS differing 2/3 baskets cannot claim savings or best price, even when cheaper partial total");
console.log("PASS identical matched-item IDs recognized independently of ordering");
console.log("NOTE isolated regression, not live retailer API test");
